def stacked_cube_surface_area(grid):
 rows,cols=len(grid),len(grid[0]);area=0
 for r in range(rows):
  for c in range(cols):
   height=grid[r][c]
   if height:area+=2+4*height
   if r:area-=2*min(height,grid[r-1][c])
   if c:area-=2*min(height,grid[r][c-1])
 return area

